import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const {db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/realtor-final111-20261019';await fs.mkdir(dir,{recursive:true});const pool=JSON.parse(await fs.readFile('artifacts/realtor-batch-20261019/remaining-pool-summary.json'));const live=JSON.parse(await fs.readFile('artifacts/realtor-batch-20261019/live-status.json'));const old=live.jobs.filter(j=>!j.provider_sid&&['cancelled','failed'].includes(j.status));if(old.length!==46||pool.broader_candidates.length!==65)throw Error('Unexpected pool');const ids=[...old.map(j=>j.contact_id),...pool.broader_candidates.map(c=>c.id)];await fs.writeFile(dir+'/authorized-ids.json',JSON.stringify({at:new Date().toISOString(),ids,oldJobs:old.map(j=>({id:j.id,contact_id:j.contact_id,status:j.status,last_error:j.last_error}))},null,2));
const failed=old.filter(j=>j.status==='failed');const events=await db('partnership_policy_events',{action_key:'in.('+failed.map(j=>'sequence:'+j.id).join(',')+')',select:'event_key,action_key,event_type,evidence',limit:'1000'});await fs.writeFile(dir+'/technical-hold-events.json',JSON.stringify(events,null,2));console.log(JSON.stringify({targets:ids.length,technical:failed.length,events:events.map(e=>({key:e.action_key,type:e.event_type,evidence:e.evidence}))},null,2));
